import type { Metadata } from "next";
import {
  HY_ENABLED,
  LOCALE_PATH,
  OG_LOCALE,
  SITE_URL,
  type Locale,
} from "@/lib/config";
import { getMessages } from "@/lib/i18n";

export function buildMetadata(locale: Locale): Metadata {
  const t = getMessages(locale);
  const { title, description } = t.meta;
  const path = LOCALE_PATH[locale];
  // Generated by `npm run og` (scripts/generate-og.mjs).
  const image = {
    url: `/og/${locale}.png`,
    width: 1200,
    height: 630,
    alt: title,
  };

  const languages: Record<string, string> = {
    en: LOCALE_PATH.en,
    ru: LOCALE_PATH.ru,
    "x-default": LOCALE_PATH.en,
  };
  if (HY_ENABLED) languages.hy = LOCALE_PATH.hy;

  const isHiddenDraft = locale === "hy" && !HY_ENABLED;

  return {
    metadataBase: new URL(SITE_URL),
    title,
    description,
    alternates: {
      canonical: path,
      languages: isHiddenDraft ? undefined : languages,
    },
    openGraph: {
      type: "website",
      url: path,
      siteName: t.footer.name,
      title,
      description,
      locale: OG_LOCALE[locale],
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [image.url],
    },
    robots: isHiddenDraft ? { index: false, follow: false } : undefined,
  };
}
